#include <esp_wifi.h>
#include <IRremote.hpp>
#include <WiFi.h>
#include <esp_now.h>

#define PRIMARY_CH 6
#define PRIMARY_MAC_OK 1
#define NODE_CAP "both"
#define NODE_BOARD "esp32"
#define PRIMARY_TMO 15000
#define REG_FAST 1000
#define INPUT_PIN 2
#define MSG_ON "1"
#define MSG_OFF "0"
#define DEBOUNCE 30
#define OUTPUT_PIN 12
#define OUT_ACTIVE HIGH
#define OUT_INIT LOW
#define LED_PIN 13
#define SERVO_PIN 14
#define IRRX_PIN 4
#define IRTX_PIN 5

uint8_t PRIMARY_MAC[6] = {0x50,0x02,0x91,0xFF,0xAA,0x1C}; String nodeId;
uint32_t hbInterval = 30000;      /* heartbeat period, ms */
uint8_t nowChannel = PRIMARY_CH;  /* OTA mode adopts the network channel at boot */
bool esnowReady = false;
unsigned long lastBoardRx = 0; bool lastIn = false; bool lastRaw = false; bool debouncing = false;
unsigned long debounceAt = 0; bool lastOut = false; int lastLed = 0; int lastServo = 90; uint32_t irLastCode = 0;
decode_type_t irLastProto = UNKNOWN; unsigned long irLastTime = 0;

bool nodeRead(); bool nodeTx(const String& body); bool nodeSendState(bool on);
bool irNodeHexValue(const String& hex, uint32_t* out); void irNodeMark(uint16_t us);
int irNodeSend(const String& hex); bool nodeSendIrTx(); void nodeSendIr(); void nodeReg(); bool nodePeerAdd();
void nodeRelink(); void nodeRx(const esp_now_recv_info_t* info, const uint8_t* data, int len);

bool nodeRead() {
  return digitalRead(INPUT_PIN) == HIGH;
}

bool nodeTx(const String& body) {
  if(!esnowReady) return false;
  String msg = "ESPNOW " + nodeId + " " + body;
  if(esp_now_send(PRIMARY_MAC, (uint8_t*)msg.c_str(), (int)msg.length()) != 0) {
    Serial.println("[NODE] send failed"); return false;
  }
  return true;
}

bool nodeSendState(bool on) {
  return nodeTx(String("STATE RELAY auto ") + String(on ? "1" : "0"));
}

/* "1FDF00FF" -> 0x1FDF00FF. Plain hex only: no sign, no "0x", no trailing junk. */
bool irNodeHexValue(const String& hex, uint32_t* out) {
  if(hex.length() == 0 || hex.length() > 8) return false;
  if(!isxdigit((unsigned char)hex.charAt(0))) return false;
  if(hex.length() > 1 && hex.charAt(0) == '0' && (hex.charAt(1) == 'x' || hex.charAt(1) == 'X')) return false;
  char* end = NULL; uint32_t v = (uint32_t)strtoul(hex.c_str(), &end, 16);
  if(end != hex.c_str() + hex.length()) return false;
  *out = v; return true;
}

/* 38 kHz carrier: 13 us on + 13 us off. Generated here on purpose - the
   library's sendNEC() is broken/mismatched on the ESP8266 core we target. */
void irNodeMark(uint16_t us) {
  unsigned long end = micros() + us;
  do {
    digitalWrite(IRTX_PIN, HIGH); delayMicroseconds(13); digitalWrite(IRTX_PIN, LOW); delayMicroseconds(13);
  } while(micros() < end); }

int irNodeSend(const String& hex) {
  uint32_t vhex = 0;
  if(!irNodeHexValue(hex, &vhex) || vhex == 0) {
    Serial.println("[NODE] IR TX FAIL: bad code"); return -1;
  }
  char hx[9]; snprintf(hx, sizeof(hx), "%08lX", (unsigned long)vhex); Serial.print("[NODE] IR TX START 0x");
  Serial.print(hx); Serial.println(" @ 38Hz");

  pinMode(IRTX_PIN, OUTPUT); digitalWrite(IRTX_PIN, LOW); irNodeMark(9000); delayMicroseconds(4500);
  for(uint8_t bit = 0; bit < 32; bit++) {
    irNodeMark(560); delayMicroseconds(((vhex >> bit) & 1UL) ? 1690 : 560);
  }
  irNodeMark(560); digitalWrite(IRTX_PIN, LOW); Serial.println("[NODE] IR TX OK"); return 1;
}

bool nodeSendIrTx() {
  return nodeTx("STATE IRTX auto ok");
}

void nodeSendIr() {
  if(!IrReceiver.decode()) return;

  /* One exit path: whatever we do not report still has to release the receiver. */
  uint8_t flags = IrReceiver.decodedIRData.flags; uint32_t code = (uint32_t)IrReceiver.decodedIRData.decodedRawData;
  decode_type_t proto = IrReceiver.decodedIRData.protocol; bool ok = IrReceiver.irparams.rawlen >= 12;
  if(flags & (IRDATA_FLAGS_IS_REPEAT | IRDATA_FLAGS_IS_AUTO_REPEAT | IRDATA_FLAGS_WAS_OVERFLOW)) ok = false;
  if(proto == irLastProto && code == irLastCode && millis() - irLastTime < 250) ok = false;
  irLastCode = code; irLastProto = proto; irLastTime = millis();

  /* Only decoded protocols have a code to report. */
  if(proto == UNKNOWN || proto == PULSE_WIDTH || proto == PULSE_DISTANCE) ok = false;

  if(ok) {
    char hex[16]; snprintf(hex, sizeof(hex), "%08lX", (unsigned long)code); String protoName = "UNKNOWN";
    switch(proto) {
      case NEC: protoName = "NEC"; break; case SONY: protoName = "SONY"; break; case RC5: protoName = "RC5"; break;
      case RC6: protoName = "RC6"; break; case SAMSUNG: protoName = "SAMSUNG"; break;
      case JVC: protoName = "JVC"; break; case LG: protoName = "LG"; break; default: break;
    }
    nodeTx(String("SENSOR IR auto ") + protoName + ":" + String(hex));
  }
  IrReceiver.resume();
}

void nodeReg() {
  nodeTx(String("REGISTER ") + NODE_BOARD + ":" + NODE_CAP);
}

/* (Re)register the Primary MAC at the current channel - used by boot and by relink. */
bool nodePeerAdd() {
  if(esp_now_is_peer_exist(PRIMARY_MAC)) esp_now_del_peer(PRIMARY_MAC);
  esp_now_peer_info_t peer = {}; memcpy(peer.peer_addr, PRIMARY_MAC, 6); peer.channel = nowChannel;
  peer.encrypt = false;
  if(esp_now_add_peer(&peer) != ESP_OK) {
    Serial.println("[NODE] peer add failed"); return false;
  }
  return true;
}

void nodeRelink() {
  if(!esnowReady || !nodePeerAdd()) return;
  nodeReg();
}

void nodeRx(const esp_now_recv_info_t* info, const uint8_t* data, int len) {
  if(!esnowReady || !data || len < 8) return;
  if(memcmp(info->src_addr, PRIMARY_MAC, 6) != 0) return; /* drop frames from any peer other than the paired Hero board */
  String msg; msg.concat((const char*)data, len);  /* ESP8266 core has no String(char*,len) ctor */
  if(!msg.startsWith("ESPNOW ")) return;
  int s1 = msg.indexOf(' ', 7);
  if(s1 < 0) return;
  String sender = msg.substring(7, s1);
  if(sender.length() == 0 || sender == nodeId) return;
  lastBoardRx = millis(); String rest = msg.substring(s1 + 1); int s2 = rest.indexOf(' ');
  String type = (s2 < 0) ? rest : rest.substring(0, s2); String tok = (s2 < 0) ? "" : rest.substring(s2 + 1);
  if(type == "SET") {
    int ci = tok.lastIndexOf(':');
    if(ci == -1) return;
    String target = tok.substring(0, ci); String val = tok.substring(ci + 1);
    if(target == "relay") {
      bool on = (val == "1" || val == "on" || val == "ON" || val == "HIGH");
      digitalWrite(OUTPUT_PIN, on ? OUT_ACTIVE : (OUT_ACTIVE == HIGH ? LOW : HIGH)); lastOut = on;
      Serial.println("[NODE] output " + String(on ? "ON" : "OFF")); nodeSendState(on); return;
    }
    if(target == "led") {
      if(val == "1" || val == "on" || val == "ON" || val == "HIGH") val = "255";
      if(val == "0" || val == "off" || val == "OFF" || val == "LOW") val = "0";
      long lv = val.toInt();
      if(lv < 0 || lv > 255) return;
      ledcWrite(LED_PIN, (uint32_t)lv); lastLed = (int)lv; nodeTx(String("STATE LED auto ") + String(lastLed));
      return;
    }
    if(target == "servo") {
      int a = val.toInt();
      if(a < 0 || a > 180) return;
      ledcWrite(SERVO_PIN, (uint32_t)((1000L + (long)a * 1000L / 180L) * 16384L / 20000L)); lastServo = a;
      nodeTx(String("STATE SERVO auto ") + String(lastServo)); return;
    }
    if(target == "irtx") {
      if(irNodeSend(val) == 1) { Serial.println("[NODE] IR sent"); nodeSendIrTx(); }
      return;
    }
    return;
  }
  if(type == "IR_SEND") {
    if(irNodeSend(tok) == 1) nodeSendIrTx();
    return;
  }
  if(type == "GET") {
    if(tok == "relay") nodeSendState(lastOut);
    if(tok == "sensor") nodeTx(String("SENSOR MOTION auto ") + String(lastIn ? MSG_ON : MSG_OFF));
    if(tok == "ir") nodeSendIr();
    if(tok == "led") nodeTx(String("STATE LED auto ") + String(lastLed));
    if(tok == "irtx") nodeSendIrTx();
    if(tok == "servo") nodeTx(String("STATE SERVO auto ") + String(lastServo));
    return;
  }
  if(type == "PING") {
    nodeTx("PONG auto ok"); return;
  }
  if(type == "RESET") {
    Serial.println("[NODE] reset via command"); delay(50); ESP.restart(); return;
  }
}

void setup() {
  Serial.begin(115200); delay(50); WiFi.mode(WIFI_STA); esp_wifi_set_channel(PRIMARY_CH, WIFI_SECOND_CHAN_NONE);
  nodeId = "ESP32-" + WiFi.macAddress().substring(15);
  esp_wifi_set_ps(WIFI_PS_NONE); /* ESP-NOW + Wi-Fi coexistence: no radio sleep */ if(esp_now_init() != ESP_OK) {
    Serial.println("[NODE] ESP-NOW init failed");
  } else if(!PRIMARY_MAC_OK) {
    /* Zeroed MAC (no Primary Board picked) - the send would fail silently, so say it. */
    Serial.println("[NODE] NO PRIMARY BOARD — node left silent; pick the Primary Board and re-flash");
  } else if(nodePeerAdd()) {
    esp_now_register_recv_cb(nodeRx); esnowReady = true;
  }
  pinMode(INPUT_PIN, INPUT); lastIn = nodeRead(); lastRaw = lastIn; pinMode(OUTPUT_PIN, OUTPUT);
  digitalWrite(OUTPUT_PIN, OUT_INIT); lastOut = (OUT_INIT == HIGH); ledcAttach(LED_PIN, 5000, 8);
  ledcWrite(LED_PIN, 0); lastLed = 0; ledcAttach(SERVO_PIN, 50, 14); lastServo = 90;
  ledcWrite(SERVO_PIN, (uint32_t)((1000L + (long)lastServo * 1000L / 180L) * 16384L / 20000L));
  IrReceiver.begin(IRRX_PIN); /* one-arg API: no feedback LED, works on old and new IRremote */
  pinMode(IRTX_PIN, OUTPUT);         /* driven directly by irNodeMark() */
  digitalWrite(IRTX_PIN, LOW);
  nodeSendState(lastOut); nodeReg();
  Serial.println("[NODE] " + nodeId + " ready MAC=" + WiFi.macAddress() + " CH=" + String(nowChannel));
}

void loop() {
  bool v = nodeRead();
  if(v != lastRaw) { lastRaw = v; debouncing = true; debounceAt = millis(); }
  if(debouncing && millis() - debounceAt > DEBOUNCE) {
    debouncing = false;
    if(lastRaw != lastIn) {
      lastIn = lastRaw;
      Serial.println(lastIn ? "[NODE] triggered: " + String(MSG_ON) : "[NODE] clear: " + String(MSG_OFF));
      if(esnowReady) nodeTx(String("SENSOR MOTION auto ") + String(lastIn ? MSG_ON : MSG_OFF));
    }
  }
  nodeSendIr(); static unsigned long lastReg = 0; unsigned long now = millis();
  long sinceBoard = (long)(now - lastBoardRx);
  if(sinceBoard >= 0 && sinceBoard <= PRIMARY_TMO) {
    if(now - lastReg > hbInterval) { lastReg = now; nodeReg(); }
  } else {
    if(now - lastReg > REG_FAST) { lastReg = now; nodeRelink(); }
  }
  delay(20);
}

