/**
 * Restarts receiver after send. Is a NOP if sending does not require a timer.
 */
void IRrecv::restartAfterSend() {
#if defined(SEND_PWM_BY_TIMER) && !defined(SEND_PWM_DOES_NOT_USE_RECEIVE_TIMER)
    start();
#endif
}

/**
 * Disables the timer for IR reception.
 */
void IRrecv::stop() {
    timerDisableReceiveInterrupt();
}

/*
 * Stores microseconds of stop, to adjust TickCounterForISR in restartTimer()
 */
void IRrecv::stopTimer() {
    timerDisableReceiveInterrupt();
    sMicrosAtLastStopTimer = micros();
}

/**
 * Restart the ISR (Interrupt Service Routine) state machine, to enable receiving of the next IR frame.
 * Internal counting of gap timing is independent of StateForISR and therefore independent of call time of resume().
 */
void IRrecv::resume() {
    // This check allows to call resume at arbitrary places or more than once
    if (irparams.StateForISR == IR_REC_STATE_STOP) {
        irparams.StateForISR = IR_REC_STATE_IDLE;
    }
}

/**
 * Is internally called by decode before calling decoders.
 * Must be used to setup data, if you call decoders manually.
 */
void IRrecv::initDecodedIRData() {

    if (irparams.OverflowFlag) {
        decodedIRData.flags = IRDATA_FLAGS_WAS_OVERFLOW;

        DEBUG_PRINT(F("Overflow happened, try to increase the \"RAW_BUFFER_LENGTH\" value of "));
        DEBUG_PRINT(RAW_BUFFER_LENGTH);
        DEBUG_PRINTLN(F(" with #define RAW_BUFFER_LENGTH=<biggerValue>"));

    } else {
        decodedIRData.flags = IRDATA_FLAGS_EMPTY;
        // save last protocol, command and address for repeat handling (where they are compared or copied back :-))
        lastDecodedProtocol = decodedIRData.protocol; // repeat patterns can be equal between protocols (e.g. NEC, Samsung and LG), so we must keep the original one
        lastDecodedCommand = decodedIRData.command;
        lastDecodedAddress = decodedIRData.address;

    }
    decodedIRData.protocol = UNKNOWN;
    decodedIRData.command = 0;
    decodedIRData.address = 0;
    decodedIRData.decodedRawData = 0;
    decodedIRData.numberOfBits = 0;
}

/**
 * @return true if available() is true or IR receiver has not received a mark/signal since last resume().
 */
bool IRrecv::isIdle() {
    return (irparams.StateForISR == IR_REC_STATE_IDLE || available());
}

/**
 * Returns true if IR receiver has received a complete IR frame (detected by timeout after last mark).
 */
bool IRrecv::available() {
    return (irparams.StateForISR == IR_REC_STATE_STOP);
}

/**
 * Returns pointer to IrReceiver.decodedIRData if IR receiver data is available, else nullptr.
 */
IRData* IRrecv::read() {
    if (irparams.StateForISR != IR_REC_STATE_STOP) {
        return nullptr;
    }
    if (decode()) {
        return &decodedIRData;
    } else {
        return nullptr;
    }
}

/**
 * The main decode function, attempts to decode the recently receive IR signal.
 * The set of decoders used is determined by active definitions of the DECODE_<PROTOCOL> macros.
 * Results of decoding are stored in IrReceiver.decodedIRData.* like e.g. IrReceiver.decodedIRData.command.
 * @return false if no IR receiver data available, true if data available.
 */
bool IRrecv::decode() {
    if (irparams.StateForISR != IR_REC_STATE_STOP) {
        return false;
    }

    /*
     * Support for old examples, which do not use the default IrReceiver instance
     */
    if (this != &IrReceiver) {
        decodedIRData.initialGapTicks = irparams.initialGapTicks;
        decodedIRData.rawlen = irparams.rawlen;
    }

    initDecodedIRData(); // sets IRDATA_FLAGS_WAS_OVERFLOW and decodedIRData.protocol = UNKNOWN;

    if (decodedIRData.flags & IRDATA_FLAGS_WAS_OVERFLOW) {
        /*
         * Set OverflowFlag flag and return true here, to let the loop call resume or print raw data.
         */
        return true;
    }

#if defined(DECODE_NEC) || defined(DECODE_ONKYO)
    TRACE_PRINTLN(F("Attempting NEC/Onkyo decode"));
    if (decodeNEC()) {
        return true;
    }
#endif

#if defined(DECODE_OPENLASIR)
    TRACE_PRINTLN(F("Attempting OpenLASIR decode"));
    if (decodeOpenLASIR()) {
        return true;
    }
#endif

#if defined(DECODE_KASEIKYO)
    TRACE_PRINTLN(F("Attempting Panasonic/Kaseikyo decode"));
    if (decodeKaseikyo()) {
        return true;
    }
#endif

#if defined(DECODE_DENON)
    TRACE_PRINTLN(F("Attempting Denon/Sharp decode"));
    if (decodeDenon()) {
        return true;
    }
#endif

#if defined(DECODE_SONY)
    TRACE_PRINTLN(F("Attempting Sony decode"));
    if (decodeSony()) {
        return true;
    }
#endif

#if defined(DECODE_RC5) || defined(DECODE_MARANTZ)
#  if defined(DECODE_RC5) && !defined(DECODE_MARANTZ)
    TRACE_PRINTLN(F("Attempting RC5 decode"));
#  elif !defined(DECODE_RC5) && defined(DECODE_MARANTZ)
    TRACE_PRINTLN(F("Attempting Marantz decode"));
#  else
    TRACE_PRINTLN(F("Attempting RC5 and Marantz decode"));
#  endif
    if (decodeRC5()) {
        return true;
    }
#endif

#if defined(DECODE_RC6)
    TRACE_PRINTLN(F("Attempting RC6 decode"));
    if (decodeRC6()) {
        return true;
    }
#endif

#if defined(DECODE_LG)
    TRACE_PRINTLN(F("Attempting LG decode"));
    if (decodeLG()) {
        return true;
    }
#endif

#if defined(DECODE_JVC)
    TRACE_PRINTLN(F("Attempting JVC decode"));
    if (decodeJVC()) {
        return true;
    }
#endif

#if defined(DECODE_SAMSUNG)
    TRACE_PRINTLN(F("Attempting Samsung decode"));
    if (decodeSamsung()) {
        return true;
    }
#endif
    /*
     * Start of the exotic protocols
     */

#if defined(DECODE_BEO)
    TRACE_PRINTLN(F("Attempting Bang & Olufsen decode"));
    if (decodeBangOlufsen()) {
        return true;
    }
#endif

#if defined(DECODE_FAST)
    TRACE_PRINTLN(F("Attempting FAST decode"));
    if (decodeFAST()) {
        return true;
    }
#endif

#if defined(DECODE_WHYNTER)
    TRACE_PRINTLN(F("Attempting Whynter decode"));
    if (decodeWhynter()) {
        return true;
    }
#endif

#if defined(DECODE_LEGO_PF)
    TRACE_PRINTLN(F("Attempting Lego Power Functions"));
    if (decodeLegoPowerFunctions()) {
        return true;
    }
#endif

#if defined(DECODE_BOSEWAVE)
    TRACE_PRINTLN(F("Attempting Bosewave decode"));
    if (decodeBoseWave()) {
        return true;
    }
#endif

#if defined(DECODE_MAGIQUEST)
    TRACE_PRINTLN(F("Attempting MagiQuest decode"));
    if (decodeMagiQuest()) {
        return true;
    }
#endif

    /*
     * Try the universal decoder for pulse distance protocols
     */
#if defined(DECODE_DISTANCE_WIDTH)
    TRACE_PRINTLN(F("Attempting universal Distance Width decode"));
    if (decodeDistanceWidth()) {
        return true;
    }
#endif

    /*
     * Last resort is the universal hash decode which always return true
     */
#if defined(DECODE_HASH)
    TRACE_PRINTLN(F("Hash decode"));
    // decodeHash returns a hash on any input.
    // Thus, it needs to be last in the list.
    // If you add any decodes, add them before this.
    if (decodeHash()) {
        return true;
    }
#endif

    /*
     * Return true here, to let the loop decide to call resume or to print raw data.
     */
    return true;
}

/**********************************************************************************************************************
 * Common decode functions
 **********************************************************************************************************************/
/**
 * Decode pulse distance width protocols. We only check the mark or space length of a 1 against a threshold value, otherwise we always assume a 0!
 * We do not check the length of the constant pulse for the widely used PulseDistance width and the constant pause for PulseWidth (currently only sony protocol).
 * using matchMark() and matchSpace(), which includes MARK_EXCESS_MICROS in comparison.
 *
 * We can have the following protocol timings
 * PULSE_DISTANCE:       Pause/spaces have different length and determine the bit value, longer space is 1. Pulses/marks can be constant, like NEC.
 * PULSE_WIDTH:          Pulses/marks have different length and determine the bit value, longer mark is 1. Pause/spaces can be constant, like Sony.
 * PULSE_DISTANCE_WIDTH: Pulses/marks and pause/spaces have different length, often the bit length is constant, like MagiQuest. Can be decoded using the PULSE_DISTANCE decoding.
 *
 * Input is     IrReceiver.irparams.rawbuf[]
 * Output is    IrReceiver.decodedIRData.decodedRawData
 *
 * @param   aNumberOfBits           Number of bits to decode from irparams.rawbuf[] array.
 * @param   aStartOffset            Offset in irparams.rawbuf[] to start decoding. Must point to a mark.
 * @param   aOneMicros              Timing value for 1.
 * @param   aIsPulseWidthProtocol   If true, aOneMicros is the nominal mark duration for a 1, otherwise the nominal space duration.
 * @param   aMSBfirst               If true, receive Most Significant Bit first, else receive Least Significant Bit (lowest bit) first.
 */
void IRrecv::decodePulseDistanceWidthData(uint_fast8_t aNumberOfBits, IRRawlenType aStartOffset, uint16_t aOneThresholdMicros,
        bool aIsPulseWidthProtocol, bool aMSBfirst) {
#
#if defined(LOCAL_DEBUG)
    Serial.print(F("isPulseWidthProtocol="));
    Serial.print(aIsPulseWidthProtocol);
    Serial.print(F(", MARK_EXCESS_MICROS=" STR(MARK_EXCESS_MICROS) " OneThresholdMicros="));
    Serial.print(aOneThresholdMicros);
    Serial.print(F(" => a "));
    uint16_t tOneMicrosQuarter = aOneThresholdMicros / 4;
    if (aIsPulseWidthProtocol) {
        Serial.print(F("mark from "));
        Serial.print((tOneMicrosQuarter * 3) + MARK_EXCESS_MICROS + 1);
        Serial.print(F(" to "));
        Serial.print((tOneMicrosQuarter * 5) + MARK_EXCESS_MICROS);
    } else {
        Serial.print(F("space from "));
        Serial.print((tOneMicrosQuarter * 3) - MARK_EXCESS_MICROS + 1);
        Serial.print(F(" to "));
        Serial.print((tOneMicrosQuarter * 5) - MARK_EXCESS_MICROS);
    }
    Serial.println(F(" is taken as a 1"));
#endif

    IRDecodedRawDataType tDecodedData = 0; // For MSB first tDecodedData is shifted left each loop
    IRDecodedRawDataType tMask = 1UL; // Mask is only used for LSB first
    auto *tRawBufPointer = &irparams.rawbuf[aStartOffset];
    if (!aIsPulseWidthProtocol) {
        tRawBufPointer++; // PULSE_DISTANCE: we only check the spaces, so start at the first space
    }

    for (uint_fast8_t i = aNumberOfBits; i > 0; i--) {
        uint16_t tCurrentTicks = *tRawBufPointer;
        tRawBufPointer += 2; // Skip the timing, which is not evaluated
        bool tBitValue;
        if (aIsPulseWidthProtocol) {
            tBitValue = matchMark(tCurrentTicks, aOneThresholdMicros); // Check for variable length mark indicating a 1 or 0
        } else {
            tBitValue = matchSpace(tCurrentTicks, aOneThresholdMicros); // Check for variable length space indicating a 1 or 0
        }

        if (aMSBfirst) {
            tDecodedData <<= 1;
        }

        if (tBitValue) {
            // It's a 1 -> set the bit
            if (aMSBfirst) {
                tDecodedData |= 1;
            } else {
                tDecodedData |= tMask;
            }
            TRACE_PRINT(tCurrentTicks);
            TRACE_PRINTLN(F(" => 1"));
        } else {
            // do not set the bit
            TRACE_PRINT(tCurrentTicks);
            TRACE_PRINTLN(F(" => 0"));
        }
        tMask <<= 1;
    }
    decodedIRData.decodedRawData = tDecodedData;
}

/**
 * New threshold decoder to be activated by USE_THRESHOLD_DECODER
 * Assumes a 0 for shorter and a 1 for longer timing. Thus the value must be eventually inverted by the calling protocol decoder (MagiQuest).
 * In normal decoder, we check whether there is a timing for a 1 (usually the longer timing) within a range of 75 % to 125 % of the nominal timing. See TICKS_LOW.
 * Many protocols have a ratio of 1 to 3 between short and long timing. In this case this decoder extends the range to 66% and the upper bound does not matter anyway.
 * I hope that this will give slightly better results especially for
 *  - jittering signals
 *  - protocols with a smaller timing ratio than 1 to 2
 *  - protocols with short 1 pulses / pauses like MagiQuest.
 * Requires up to 458 bytes more program space, if more than 1 protocol is involved.
 * but saves 90 bytes if only e.g. NEC is selected.
 *
 * @param   aNumberOfBits           Number of bits to decode from irparams.rawbuf[] array.
 * @param   aStartOffset            Offset in irparams.rawbuf[] to start decoding. Must point to a mark.
 * @param   aOneThresholdMicros     Threshold value for 1.
 * @param   aIsPulseWidthProtocol   If true, aOneThresholdMicros is the mark threshold for 1, otherwise the space threshold.
 * @param   aMSBfirst               If true, receive Most Significant Bit first, else receive Least Significant Bit (lowest bit) first.
 */
void IRrecv::decodeWithThresholdPulseDistanceWidthData(uint_fast8_t aNumberOfBits, IRRawlenType aStartOffset,
        uint16_t aOneThresholdMicros, bool aIsPulseWidthProtocol, bool aMSBfirst) {

    DEBUG_PRINT(F("OneThresholdMicros="));
    DEBUG_PRINT(aOneThresholdMicros);
    DEBUG_PRINT(F(" isPulseWidthProtocol="));
    DEBUG_PRINT(aIsPulseWidthProtocol);
    DEBUG_PRINTLN();

    IRDecodedRawDataType tDecodedData = 0; // For MSB first tDecodedData is shifted left each loop
    IRDecodedRawDataType tMask = 1UL; // Mask is only used for LSB first
    auto *tRawBufPointer = &irparams.rawbuf[aStartOffset];
    if (!aIsPulseWidthProtocol) {
        tRawBufPointer++;
    }

    for (uint_fast8_t i = aNumberOfBits; i > 0; i--) {
        uint16_t tCurrentMicros = *tRawBufPointer * MICROS_PER_TICK;
        bool tBitValue = tCurrentMicros > aOneThresholdMicros; // Check for variable length timing indicating a 1 or 0
        tRawBufPointer += 2;

        if (aMSBfirst) {
            tDecodedData <<= 1;
        }

        if (tBitValue) {
            // It's a 1 -> set the bit
            if (aMSBfirst) {
                tDecodedData |= 1;
            } else {
                tDecodedData |= tMask;
            }
            TRACE_PRINT(tCurrentMicros);
            TRACE_PRINTLN(F(" => 1"));
        } else {
            // do not set the bit
            TRACE_PRINT(tCurrentMicros);
            TRACE_PRINTLN(F(" => 0"));
        }
        tMask <<= 1;
    }
    decodedIRData.decodedRawData = tDecodedData;
}

/*
 * Only sensible for development or very exotic requirements. - Not used yet
 * Check for additional required characteristics of timing like length of mark for a constant mark protocol,
 * where space length determines the bit value. Requires up to 194 additional bytes of program memory.
 *
 * @param   aZeroMarkMicros     For strict checks
 * @param   aZeroSpaceMicros    For strict checks
 * @return  true if decoding successful
 *
 */
bool IRrecv::decodeStrictPulseDistanceWidthData(uint_fast8_t aNumberOfBits, IRRawlenType aStartOffset, uint16_t aOneMarkMicros,
        uint16_t aOneSpaceMicros, uint16_t aZeroMarkMicros, uint16_t aZeroSpaceMicros, bool aMSBfirst) {

    auto *tRawBufPointer = &irparams.rawbuf[aStartOffset];

    bool isPulseDistanceProtocol = (aOneMarkMicros == aZeroMarkMicros); // If true, we have a constant mark -> pulse distance protocol

    IRDecodedRawDataType tDecodedData = 0; // For MSB first tDecodedData is shifted left each loop
    IRDecodedRawDataType tMask = 1UL; // Mask is only used for LSB first

    for (uint_fast8_t i = aNumberOfBits; i > 0; i--) {
        // get one mark and space pair
        unsigned int tMarkTicks;
        unsigned int tSpaceTicks;
        bool tBitValue;

        tMarkTicks = *tRawBufPointer++;
        tSpaceTicks = *tRawBufPointer++; // maybe buffer overflow for last bit, but we do not evaluate this value :-)
        if (isPulseDistanceProtocol) {
            /*
             * PULSE_DISTANCE here (aOneMarkMicros == aZeroMarkMicros)
             * We additionally check constant mark duration and in case of zero the zero space duration.
             */
            tBitValue = matchSpace(tSpaceTicks, aOneSpaceMicros); // Check for variable length space indicating a 1 or 0

            // Check for constant mark duration
            if (!matchMark(tMarkTicks, aOneMarkMicros)) {
                DEBUG_PRINT(F("Mark="));
                DEBUG_PRINT(tMarkTicks * MICROS_PER_TICK);
                DEBUG_PRINT(F(" is not "));
                DEBUG_PRINT(aOneMarkMicros);
                DEBUG_PRINT(F(". Index="));
                DEBUG_PRINT(aNumberOfBits - i);
                DEBUG_PRINT(' ');
                return false;
            }

            // in case of 0, check for zero space duration
            if (!tBitValue && !matchSpace(tSpaceTicks, aZeroSpaceMicros)) {
                DEBUG_PRINT(F("Space="));
                DEBUG_PRINT(tSpaceTicks * MICROS_PER_TICK);
                DEBUG_PRINT(F(" is not "));
                DEBUG_PRINT(aZeroSpaceMicros);
                DEBUG_PRINT(F(". Index="));
                DEBUG_PRINT(aNumberOfBits - i);
                DEBUG_PRINT(' ');
                return false;
            }

        } else {
            /*
             * PULSE_WIDTH -including PULSE_DISTANCE_WIDTH-  here.
             * We additionally check two space durations and in case of zero the zero mark duration.
             */
            tBitValue = matchMark(tMarkTicks, aOneMarkMicros); // Check for variable length mark indicating a 1 or 0

            // Check for space length, which is not constant in case of PULSE_DISTANCE_WIDTH
            if ((tBitValue && !matchSpace(tSpaceTicks, aOneSpaceMicros))
                    || ((!tBitValue && !matchSpace(tSpaceTicks, aZeroSpaceMicros)))) {
                DEBUG_PRINT(F("Space="));
                DEBUG_PRINT(tSpaceTicks * MICROS_PER_TICK);
                DEBUG_PRINT(F(" is not "));
                DEBUG_PRINT(aOneSpaceMicros);
                DEBUG_PRINT(F(" or "));
                DEBUG_PRINT(aZeroSpaceMicros);
                DEBUG_PRINT(F(". Index="));
                DEBUG_PRINT(aNumberOfBits - i);
                DEBUG_PRINT(' ');
                return false;
            }
            if (!tBitValue && !matchMark(tMarkTicks, aZeroMarkMicros)) {
                DEBUG_PRINT(F("Mark="));
                DEBUG_PRINT(tMarkTicks * MICROS_PER_TICK);
                DEBUG_PRINT(F(" is not "));
                DEBUG_PRINT(aZeroMarkMicros);
                DEBUG_PRINT(F(". Index="));
                DEBUG_PRINT(aNumberOfBits - i);
                DEBUG_PRINT(' ');
                return false;
            }
        }

        if (aMSBfirst) {
            tDecodedData <<= 1;
        }

        if (tBitValue) {
            // It's a 1 -> set the bit
            if (aMSBfirst) {
                tDecodedData |= 1;
            } else {
                tDecodedData |= tMask;
            }
            TRACE_PRINTLN(F("=> 1"));
        } else {
            // do not set the bit
            TRACE_PRINTLN(F("=> 0"));
        }
        tMask <<= 1;
    }
    decodedIRData.decodedRawData = tDecodedData;
    return true;
}

/**
 * Decode pulse distance protocols for PulseDistanceWidthProtocolConstants.
 * @return  true if decoding was successful and -if USE_STRICT_DECODER is defined- false if strict checks fail
 */
bool IRrecv::decodePulseDistanceWidthData(PulseDistanceWidthProtocolConstants *aProtocolConstants, uint_fast8_t aNumberOfBits,
        IRRawlenType aStartOffset) {

#if defined(USE_STRICT_DECODER)
        return decodeStrictPulseDistanceWidthData(aNumberOfBits, aStartOffset, aProtocolConstants->DistanceWidthTimingInfo.OneMarkMicros,
                aProtocolConstants->DistanceWidthTimingInfo.OneSpaceMicros, aProtocolConstants->DistanceWidthTimingInfo.ZeroMarkMicros,
                aProtocolConstants->DistanceWidthTimingInfo.ZeroSpaceMicros, (aProtocolConstants->Flags & PROTOCOL_IS_MSB_MASK));

#else
    bool tIsPulseWidthProtocol = aProtocolConstants->Flags & PROTOCOL_IS_PULSE_WIDTH_MASK;
    uint16_t tThresholdMicros;

#  if defined(USE_THRESHOLD_DECODER)
        if (tIsPulseWidthProtocol) {
            // we check the length of marks here
            tThresholdMicros = ((aProtocolConstants->DistanceWidthTimingInfo.OneMarkMicros
                            + aProtocolConstants->DistanceWidthTimingInfo.ZeroMarkMicros) / 2) + MARK_EXCESS_MICROS;// MARK_EXCESS_MICROS is 0 here if not explicitly specified by user
        } else {
            // we check the length of spaces here
            tThresholdMicros = ((aProtocolConstants->DistanceWidthTimingInfo.OneSpaceMicros
                            + aProtocolConstants->DistanceWidthTimingInfo.ZeroSpaceMicros) / 2) - MARK_EXCESS_MICROS;// MARK_EXCESS_MICROS is 0 here if not explicitly specified by user
        }
        decodeWithThresholdPulseDistanceWidthData(aNumberOfBits, aStartOffset, tThresholdMicros,
                aProtocolConstants->Flags & PROTOCOL_IS_PULSE_WIDTH_MASK, (aProtocolConstants->Flags & PROTOCOL_IS_MSB_MASK));
#  else
    if (tIsPulseWidthProtocol) {
        tThresholdMicros = aProtocolConstants->DistanceWidthTimingInfo.OneMarkMicros;
    } else {
        tThresholdMicros = aProtocolConstants->DistanceWidthTimingInfo.OneSpaceMicros;
    }
    decodePulseDistanceWidthData(aNumberOfBits, aStartOffset, tThresholdMicros,
            aProtocolConstants->Flags & PROTOCOL_IS_PULSE_WIDTH_MASK, (aProtocolConstants->Flags & PROTOCOL_IS_MSB_MASK));
#  endif
#endif
    return true;
}

bool IRrecv::decodePulseDistanceWidthData_P(PulseDistanceWidthProtocolConstants const *aProtocolConstantsPGM,
        uint_fast8_t aNumberOfBits, IRRawlenType aStartOffset) {

    PulseDistanceWidthProtocolConstants tTemporaryPulseDistanceWidthProtocolConstants;
    memcpy_P(&tTemporaryPulseDistanceWidthProtocolConstants, aProtocolConstantsPGM,
            sizeof(tTemporaryPulseDistanceWidthProtocolConstants));

    return decodePulseDistanceWidthData(&tTemporaryPulseDistanceWidthProtocolConstants, aNumberOfBits, aStartOffset);
}

/**********************************************************************************************************************
 * Internal Hash decode function
 **********************************************************************************************************************/
#define FNV_PRIME_32 16777619   ///< used for decodeHash()
#define FNV_BASIS_32 2166136261 ///< used for decodeHash()

/**
 * Compare two (tick) values for Hash decoder
 * Use a tolerance of 20% to enable e.g. 500 and 600 (NEC timing) and at least 200 and 250 to be equal
 * @return  0 if newval is shorter, 1 if newval is equal, and 2 if newval is longer
 */
uint_fast8_t IRrecv::compare(uint16_t aOldValue, uint16_t aNewValue) {
    if (aNewValue * 10 < aOldValue * 8) {
        return 0;
    }
    if (aOldValue * 10 < aNewValue * 8) {
        return 2;
    }
    return 1;
}

/**
 * Decodes an arbitrary IR code to a 32-bit value.
 * Instead of decoding using a standard encoding scheme
 * (e.g. Sony, NEC, RC5), the code is hashed to a 32-bit value.
 *
 * The algorithm looks at the sequence of MARK and SPACE signals, and see if each one
 * is more than 20% shorter (0), the same (+/- 20%) length (1), or more than 20% longer (2) than the previous MARK or SPACE.
 * It hash the resulting sequence of 0's, 1's, and 2's to a 32-bit value.
 * This will give a unique value for each different code (probably), for most code systems.
 *
 * Uses FNV hash algorithm: http://isthe.com/chongo/tech/comp/fnv/#FNV-param
 * Converts the raw code values into a 32-bit hash code.
 * Hopefully this code is unique for each button.
 * This isn't a "real" decoding, just an arbitrary value.
 *
 * see: http://www.righto.com/2010/01/using-arbitrary-remotes-with-arduino.html
 */
bool IRrecv::decodeHash() {
    unsigned long hash = FNV_BASIS_32; // the result is the same no matter if we use a long or unsigned long variable

// Require at least 6 samples to prevent triggering on noise
    if (decodedIRData.rawlen < 6) {
        DEBUG_PRINT(F("HASH: Data length="));
        DEBUG_PRINT(decodedIRData.rawlen);
        DEBUG_PRINTLN(F(" is less than 6"));
        return false;
    }
    for (IRRawlenType i = 1; (i + 2) < decodedIRData.rawlen; i++) {
        // Compare mark with mark and space with space
        uint_fast8_t value = compare(irparams.rawbuf[i], irparams.rawbuf[i + 2]);
        // Add value into the hash - (0 if rawbuf[i + 2] is more than 20 % shorter, 1 if rawbuf[i + 2] is equal, and 2 if rawbuf[i + 2] is longer than rawbuf[i])
        hash = (hash * FNV_PRIME_32) ^ value;
    }

    decodedIRData.decodedRawData = hash;
    decodedIRData.numberOfBits = 32;
    decodedIRData.protocol = UNKNOWN;

    return true;
}

/**********************************************************************************************************************
 * Match functions
 **********************************************************************************************************************/

/*
 * returns true if values do match
 */
bool IRrecv::checkHeader(PulseDistanceWidthProtocolConstants *aProtocolConstants) {
// Check header "mark" and "space"
    if (!matchMark(irparams.rawbuf[1], aProtocolConstants->DistanceWidthTimingInfo.HeaderMarkMicros)) {
        TRACE_PRINT(::getProtocolString(aProtocolConstants->ProtocolIndex));
        TRACE_PRINTLN(F(": Header mark length is wrong"));
        return false;
    }
    if (!matchSpace(irparams.rawbuf[2], aProtocolConstants->DistanceWidthTimingInfo.HeaderSpaceMicros)) {
        TRACE_PRINT(::getProtocolString(aProtocolConstants->ProtocolIndex));
        TRACE_PRINTLN(F(": Header space length is wrong"));
        return false;
    }
    return true;
}

bool IRrecv::checkHeader_P(PulseDistanceWidthProtocolConstants const *aProtocolConstantsPGM) {
// Check header "mark" and "space"
    if (!matchMark(irparams.rawbuf[1], pgm_read_word(&aProtocolConstantsPGM->DistanceWidthTimingInfo.HeaderMarkMicros))) {
        TRACE_PRINT(::getProtocolString((decode_type_t ) pgm_read_byte(&aProtocolConstantsPGM->ProtocolIndex)));
        TRACE_PRINTLN(F(": Header mark length is wrong"));
        return false;
    }
    if (!matchSpace(irparams.rawbuf[2], pgm_read_word(&aProtocolConstantsPGM->DistanceWidthTimingInfo.HeaderSpaceMicros))) {
        TRACE_PRINT(::getProtocolString((decode_type_t ) pgm_read_byte(&aProtocolConstantsPGM->ProtocolIndex)));
        TRACE_PRINTLN(F(": Header space length is wrong"));
        return false;
    }
    return true;
}

/*
 * Does not check for same address and command, because it is almost not possible to press 2 different buttons on the remote within around 100 ms.
 * And if really required, it can be enabled here, or done manually in user program.
 * And we have still no RC6 toggle bit check for detecting a second press on the same button.
 */
void IRrecv::checkForRepeatSpaceTicksAndSetFlag(uint16_t aMaximumRepeatSpaceTicks) {
    if (decodedIRData.initialGapTicks < aMaximumRepeatSpaceTicks
#if defined(ENABLE_COMPLETE_REPEAT_CHECK)
// Check also for same command and address values to detect a repeat. Not sensible for standard protocols, because it is almost not possible to press 2 different buttons on the remote within around 100 ms
                && decodedIRData.address == lastDecodedAddress && decodedIRData.command == lastDecodedCommand /* requires around 44 bytes program space */
#endif
            ) {
        decodedIRData.flags |= IRDATA_FLAGS_IS_REPEAT;
    }
}

/**
 * Match function with compensating for marks exceeded or spaces shortened by demodulator hardware
 * With aCompensationMicrosForTicks = 0 we need 4 bytes program space compared to completely removing the value.
 * Match is true, if signal value is bigger/equal 75% and less/equal 125% of aMatchValueMicros.
 * @param aCompensationMicrosForTicks is set to MARK_EXCESS_MICROS (matchSpace) and -MARK_EXCESS_MICROS (matchMark)
 *               With MARK_EXCESS_MICROS default value of 20 we cannot match mark 200 to 250, because we have 186 < 180 (=200-20) <= 310
 * @return true, if values match
 */
bool matchTicks(uint16_t aMeasuredTicks, uint16_t aMatchValueMicros, int16_t aCompensationMicrosForTicks) {
    uint16_t tMeasuredMicros = (aMeasuredTicks * MICROS_PER_TICK) + aCompensationMicrosForTicks;
    uint16_t tMatchValueMicrosQuarter = aMatchValueMicros / 4;

    TRACE_PRINT(F("Testing (actual vs desired): "));
    TRACE_PRINT(tMeasuredMicros);
    TRACE_PRINT(F("us vs "));
    TRACE_PRINT(aMatchValueMicros);
    TRACE_PRINT(F("us: "));
    TRACE_PRINT(tMatchValueMicrosQuarter * 3); // rounded value because we divide first
    TRACE_PRINT(F(" < "));
    TRACE_PRINT(tMeasuredMicros);
    TRACE_PRINT(F(" <= "));
    TRACE_PRINT(tMatchValueMicrosQuarter * 5);

    bool passed = (tMeasuredMicros > (tMatchValueMicrosQuarter * 3) && tMeasuredMicros <= (tMatchValueMicrosQuarter * 5));
#if defined(LOCAL_TRACE)
    if (passed) {
        Serial.println(F(" => passed"));
    } else {
        Serial.println(F(" => failed"));
    }
#endif
    return passed;
}

bool matchTicksWithGreaterRange(uint16_t aMeasuredTicks, uint16_t aMatchValueMicros, int16_t aCompensationMicrosForTicks) {
    uint16_t tMeasuredMicros = (aMeasuredTicks * MICROS_PER_TICK) + aCompensationMicrosForTicks;
    uint16_t tMatchValueMicrosQuarter = aMatchValueMicros / 4;

    TRACE_PRINT(F("Testing with greater range (actual vs desired): "));
    TRACE_PRINT(tMeasuredMicros);
    TRACE_PRINT(F("us vs "));
    TRACE_PRINT(aMatchValueMicros);
    TRACE_PRINT(F("us: "));
    TRACE_PRINT(tMatchValueMicrosQuarter * 2); // rounded value because we divide first
    TRACE_PRINT(F(" < "));
    TRACE_PRINT(tMeasuredMicros);
    TRACE_PRINT(F(" <= "));
    TRACE_PRINT(tMatchValueMicrosQuarter * 6);

    bool passed = (tMeasuredMicros > (tMatchValueMicrosQuarter * 2) && tMeasuredMicros <= (tMatchValueMicrosQuarter * 6));
#if defined(LOCAL_TRACE)
    if (passed) {
        Serial.println(F(" => passed"));
    } else {
        Serial.println(F(" => failed"));
    }
#endif
    return passed;
}

/**
 * Compensate for marks exceeded by demodulator hardware
 * @return true, if values match
 */
bool matchMark(uint16_t aMeasuredTicks, uint16_t aMatchValueMicros) {
    return matchTicks(aMeasuredTicks, aMatchValueMicros, -MARK_EXCESS_MICROS);
}

bool matchMarkWithGreaterRange(uint16_t aMeasuredTicks, uint16_t aMatchValueMicros) {
    return matchTicksWithGreaterRange(aMeasuredTicks, aMatchValueMicros, -MARK_EXCESS_MICROS);
}

/**
 * Compensate for spaces shortened by demodulator hardware
 * @return true, if values match
 */
bool matchSpace(uint16_t aMeasuredTicks, uint16_t aMatchValueMicros) {
    return matchTicks(aMeasuredTicks, aMatchValueMicros, MARK_EXCESS_MICROS);
}

bool matchSpaceWithGreaterRange(uint16_t aMeasuredTicks, uint16_t aMatchValueMicros) {
    return matchTicksWithGreaterRange(aMeasuredTicks, aMatchValueMicros, MARK_EXCESS_MICROS);
}

/**
 * Getter function for MARK_EXCESS_MICROS
 */
int getMarkExcessMicros() {
    return MARK_EXCESS_MICROS;
}

/**
 * Checks if detected space between two transmissions is smaller than known value for protocols (12 ms for Sony20 protocols)
 * @return true, if CheckForRecordGapsMicros() has printed a message, i.e. gap < 15ms (RECORD_GAP_MICROS_WARNING_THRESHOLD)
 */
bool IRrecv::checkForRecordGapsMicros(Print *aSerial) {
    /*
     * Check if detected space between two transmissions is smaller than known value for protocols (12 ms for Sony20 protocol)
     */
    if (decodedIRData.initialGapTicks < (RECORD_GAP_MICROS_WARNING_THRESHOLD / MICROS_PER_TICK)) {
        aSerial->println();
        aSerial->print(F("Space of "));
        aSerial->print(decodedIRData.initialGapTicks * MICROS_PER_TICK);
        aSerial->print(F(" us between two detected transmission is smaller than the minimal gap of "));
        aSerial->print(RECORD_GAP_MICROS_WARNING_THRESHOLD);
        aSerial->println(F(" us known for implemented protocols like NEC, Sony, RC5 etc.."));
        aSerial->println(F("But it can be OK for some yet unsupported protocols, and especially for repeats."));
        aSerial->println(F("If you get unexpected results, try to increase the RECORD_GAP_MICROS in IRremote.hpp."));
        aSerial->println();
        return true;
    }
    return false;
}

