void timerConfigForSend(uint16_t aFrequencyKHz) {
//#    if ESP_ARDUINO_VERSION >= ESP_ARDUINO_VERSION_VAL(3, 0, 0)
#    if ESP_ARDUINO_VERSION >= (3 << 16 | 0 << 8 | 0)
