        ledcDetach(IR_SEND_PIN); // detach pin before new attaching see #1194
        ledcAttach(IR_SEND_PIN, aFrequencyKHz * 1000, _IRREMOTE_ESP32_LEDC_RESOLUTION); // 3.x API
        sLastFrequencyKHz = aFrequencyKHz;
