/** \addtogroup Decoder Decoders and encoders for different protocols
 * @{
 */
// generated with https://patorjk.com/software/taag/#p=display&f=Alphabet&t=FAST
//==============================================================================
//                             FFFF   AA    SSS  TTTTTT
//                             F     A  A  S       TT
//                             FFF   AAAA   SSS    TT
//                             F     A  A      S   TT
//                             F     A  A  SSSS    TT
//==============================================================================
#include "TinyIR.h"
/*
 Protocol=FAST Address=0x0 Command=0x76 Raw-Data=0x8976 16 bits LSB first
 +2100,-1050
 + 550,- 500 + 550,-1550 + 550,-1550 + 550,- 500
 + 550,-1550 + 550,-1550 + 550,-1550 + 550,- 500
 + 550,-1550 + 550,- 500 + 550,- 500 + 550,-1550
 + 550,- 500 + 550,- 500 + 550,- 500 + 550,-1550
 + 550
 Sum: 28900
 */
struct PulseDistanceWidthProtocolConstants const FASTProtocolConstants PROGMEM = { FAST, FAST_KHZ, FAST_HEADER_MARK,
FAST_HEADER_SPACE, FAST_BIT_MARK, FAST_ONE_SPACE, FAST_BIT_MARK, FAST_ZERO_SPACE, PROTOCOL_IS_LSB_FIRST
        | PROTOCOL_IS_PULSE_DISTANCE, (FAST_REPEAT_PERIOD / MICROS_IN_ONE_MILLISECOND), nullptr };

/************************************
 * Start of send and decode functions
 ************************************/

/*
 * LSB first, send header, command, inverted command and stop bit
 */
void IRsend::sendFAST(uint8_t aCommand, int_fast8_t aNumberOfRepeats) {
    uint16_t tData = aCommand | (((uint16_t)((uint8_t)(~aCommand)) << 8));
    sendFAST16Bit(tData, aNumberOfRepeats);
}

/**
 * The FAST protocol repeats by skipping the header mark and space -> this leads to a poor repeat detection for this protocol.
 * @param aNumberOfRepeats  If < 0 then a regular frame will be sent as repeat frame.
 */
void IRsend::sendFAST16Bit(uint16_t aCommand, int_fast8_t aNumberOfRepeats) {
    // Set IR carrier frequency
    enableIROut(FAST_KHZ); // 38 kHz
    sendPulseDistanceWidth_P(&FASTProtocolConstants, aCommand, FAST_BITS, aNumberOfRepeats);
}

bool IRrecv::decodeFAST() {

//    uint_fast8_t tRawlen = decodedIRData.rawlen; // Using a local variable does not improve code size

    // Check we have the right amount of data (36). The +4 is for initial gap, start bit mark and space + stop bit mark.
    if (decodedIRData.rawlen != ((2 * FAST_BITS) + 4)) {
        DEBUG_PRINT(F("FAST: Data length="));
        DEBUG_PRINT(decodedIRData.rawlen);
        DEBUG_PRINTLN(F(" is not 36"));
        return false;
    }

    if (!checkHeader_P(&FASTProtocolConstants)) {
        return false;
    }

    decodePulseDistanceWidthData_P(&FASTProtocolConstants, FAST_BITS);
    WordUnion tValue;
    tValue.UWord = decodedIRData.decodedRawData;

    if (tValue.UByte.LowByte != (uint8_t) ~(tValue.UByte.HighByte)) {
        DEBUG_PRINT(F("FAST: 8 bit parity is not correct. Expected=0x"));
        DEBUG_PRINT((uint8_t) ~(tValue.UByte.LowByte), HEX);
        DEBUG_PRINT(F(" received=0x"));
        DEBUG_PRINT(tValue.UByte.HighByte, HEX);
        DEBUG_PRINT(F(" data=0x"));
        DEBUG_PRINTLN(tValue.UWord, HEX);

        decodedIRData.flags = IRDATA_FLAGS_PARITY_FAILED;
    }

    checkForRepeatSpaceTicksAndSetFlag(FAST_MAXIMUM_REPEAT_DISTANCE / MICROS_PER_TICK);

    // Success
//    decodedIRData.flags = IRDATA_FLAGS_IS_LSB_FIRST; // Not required, since this is the start value
    decodedIRData.command = tValue.UByte.LowByte;
    decodedIRData.address = 0; // No address for this protocol
    decodedIRData.numberOfBits = FAST_BITS;
    decodedIRData.protocol = FAST;

    return true;
}

/** @}*/
#include "LocalDebugLevelEnd.h"

#endif // _IR_FAST_HPP

