uint8_t sLastSendToggleValue = 1; // To start first command with toggle 0. Only required for biphase protocols.

//==============================================================================
//     RRRR    CCCC  55555
//     R   R  C      5
//     RRRR   C      5555
//     R  R   C          5
//     R   R   CCCC  5555
//==============================================================================
/*
